contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 quantity) public payable {
        require(quantity > 0 && quantity <= 1000);
        address self = address(this);
        c.adjustAdminAccess(self, true); if (__ESBMC_reverted()) return;
        c.setAllowedBurningAddresses(self); if (__ESBMC_reverted()) return;
        c.createGameItem("pbt", "uri", false, true, 0, 0, 100); if (__ESBMC_reverted()) return;
        uint256 tokenId = c.uniqueTokensOutstanding() - 1;
        c.mint(tokenId, quantity); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = c.balanceOf(self, tokenId); if (__ESBMC_reverted()) return;
        c.burn(self, tokenId, quantity); if (__ESBMC_reverted()) return;
        uint256 afterBalance = c.balanceOf(self, tokenId); if (__ESBMC_reverted()) return;
        assert(beforeBalance == quantity && afterBalance == 0);
    }

    receive() external payable {}
}

