    }

    function _run(uint256 quantity) internal {
        quantity = bound(quantity, 1, 1000);
        address self = address(this);
        try c.adjustAdminAccess(self, true) {} catch { return; }
        try c.setAllowedBurningAddresses(self) {} catch { return; }
        try c.createGameItem("pbt", "uri", false, true, 0, 0, 100) {} catch { return; }
        uint256 tokenId = c.uniqueTokensOutstanding() - 1;
        try c.mint(tokenId, quantity) {} catch { return; }
        uint256 beforeBalance;
        try c.balanceOf(self, tokenId) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
